'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var dlarnv = require( './../lib/dlarnv.js' );


// FIXTURES //

var IDIST1_SMALL = require( './fixtures/idist1_small.json' );
var IDIST1_MEDIUM = require( './fixtures/idist1_medium.json' );
var IDIST2_SMALL = require( './fixtures/idist2_small.json' );
var IDIST2_MEDIUM = require( './fixtures/idist2_medium.json' );
var IDIST3_SMALL = require( './fixtures/idist3_small.json' );
var IDIST3_MEDIUM = require( './fixtures/idist3_medium.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlarnv, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 4', function test( t ) {
	t.strictEqual( dlarnv.length, 4, 'returns expected value' );
	t.end();
});

tape( 'the function returns a vector of random numbers from a uniform (0,1) distribution (idist=1, small N)', function test( t ) {
	var iseed;
	var data;
	var x;

	data = IDIST1_SMALL;

	iseed = new Int32Array( data.ISEED );
	x = new Float64Array( data.X );

	dlarnv( data.idist, iseed, data.N, x );
	t.deepEqual( x, new Float64Array( data.X_out ), 'returns expected value' );
	t.deepEqual( iseed, new Int32Array( data.ISEED_out ), 'returns expected value' );

	t.end();
});

